-- Slice 3b regression test: CSS transform:scale() on a fixed-layout "text layer".
--
-- Renders fxl_transform.epub (generated by crengine's
-- make_fixedlayout_test_epub.py) at its native viewport size, so the page maps
-- 1:1 to the output buffer (no scaling). The page is built like a PDTron-style
-- fixed-layout book: a full-page #layer container is scaled down with
--   transform: scale(0.03125); transform-origin: left bottom;
-- and its children are positioned in the un-scaled (40x) coordinate system with
-- huge px offsets and a huge font-size. The engine folds the container's scale
-- into each child's offsets, size and font-size, so a child coordinate C lands
-- at viewport C/40. scale=0.025 is deliberately not a multiple of 1/256, so a
-- scale kept at only 1/256 precision would misplace the high-'bottom' green box
-- by ~70px and fail here. With origin left-bottom, 'left' is from x=0 and
-- 'bottom' up from y=1200:
--   #green left 2000  bottom 46000  4000x2000  -> x[50,150]   y[0,50]
--   #blue  left 2000  bottom 24000  4000x4000  -> x[50,150]   y[500,600]
--   #red   left 26000 bottom 2000   4000x6000  -> x[650,750]  y[1000,1150]
--   #text  left 4000  bottom 4000   font 1280px (-> 32px), magenta background
-- The #text box is content-height: with its font-size scaled to 32px it is a
-- ~32px tall band near the bottom; were the font NOT scaled (1280px) the box
-- would be ~1280px tall and cover the middle of the page. We assert both the
-- band's presence low down and that the middle stays the white background.
local DATA = "spec/front/unit/data/fixedlayout/"
local VP_W, VP_H = 800, 1200

describe("Fixed-layout CSS transform:scale()", function()
    local DocumentRegistry, Blitbuffer

    setup(function()
        require("commonrequire")
        DocumentRegistry = require("document/documentregistry")
        Blitbuffer = require("ffi/blitbuffer")
    end)

    -- Render page `pageno` of the book to an RGB32 buffer at viewport size.
    local function render(pageno)
        local doc = DocumentRegistry:openDocument(DATA .. "fxl_transform.epub")
        assert.truthy(doc, "could not open fxl_transform.epub")
        assert.is_true(doc:loadDocument())
        assert.are.equal(1, doc:getFixedLayoutMode())
        doc.render_color = true
        doc:setViewDimen({ w = VP_W, h = VP_H })
        doc:render()
        local bb = Blitbuffer.new(VP_W, VP_H, Blitbuffer.TYPE_BBRGB32)
        bb:fill(Blitbuffer.COLOR_BLACK) -- a colour no box uses, so a miss is obvious
        doc:drawCurrentViewByPage(bb, 0, 0, { x = 0, y = 0, w = VP_W, h = VP_H }, pageno)
        return doc, bb
    end

    -- Assert the pixel at (x,y) is approximately (r,g,b).
    local function assertPixel(bb, x, y, r, g, b, label)
        local c = bb:getPixel(x, y)
        local pr, pg, pb = c:getR(), c:getG(), c:getB()
        local tol = 20
        local ok = math.abs(pr - r) <= tol and math.abs(pg - g) <= tol and math.abs(pb - b) <= tol
        assert.is_true(ok, string.format(
            "%s at (%d,%d): expected ~(%d,%d,%d), got (%d,%d,%d)",
            label, x, y, r, g, b, pr, pg, pb))
    end

    it("folds an ancestor scale() into offsets, size and font-size", function()
        local doc, bb = render(1)

        -- Positioned, sized boxes: left/bottom and width/height scaled by 1/40,
        -- anchored by the left-bottom transform origin.
        assertPixel(bb, 100, 25,   0x3b, 0xb0, 0x4e, "green (top, bottom:46000)")
        assertPixel(bb, 100, 550,  0x2e, 0x8b, 0xe6, "blue (middle)")
        assertPixel(bb, 700, 1075, 0xe6, 0x3b, 0x2e, "red (bottom-right)")

        -- Text layer: its magenta content box sits at the scaled baseline low on
        -- the page (font-size folded 1280px -> 32px).
        assertPixel(bb, 185, 1095, 0xc0, 0x30, 0xc0, "text box (scaled baseline)")
        -- ...and does NOT reach the middle of the page, which it would if the
        -- 1280px font-size had not been scaled (a ~1280px-tall box). This is the
        -- assertion that specifically catches an unscaled font.
        assertPixel(bb, 120, 850,  0xff, 0xff, 0xff, "no giant (unscaled) text box")

        -- Kern row (an inline row of margin-positioned boxes, like a page number):
        --   #kg green at x~90 (start), #kb blue pushed right by margin-left:12000px
        --   (-> 300px), #kr red pulled back by margin-left:-11200px (-> -280px).
        -- Blue present proves inline margins are folded by the scale (unfolded it
        -- would be ~12000px off-screen); red present at x~270 proves a negative
        -- inline margin is honoured (ignored, red would sit right of blue, not here).
        assertPixel(bb, 90,  330,  0x3b, 0xb0, 0x4e, "kern green (row start)")
        assertPixel(bb, 470, 330,  0x2e, 0x8b, 0xe6, "kern blue (folded +margin)")
        assertPixel(bb, 270, 330,  0xe6, 0x3b, 0x2e, "kern red (folded -margin)")

        -- Uncovered points keep the white page background.
        assertPixel(bb, 400, 200,  0xff, 0xff, 0xff, "white background (upper)")
        assertPixel(bb, 700, 500,  0xff, 0xff, 0xff, "white background (right)")

        bb:free()
        doc:close()
    end)
end)
